import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class PublicExamplesTest{@Test void stringsIntegersAndBothFailures()throws Exception{for(int kind=0;kind<2;kind++){Object q=TaskBinding.create(kind,2);Exception e=assertThrows(Exception.class,()->TaskBinding.pop(q));assertTrue(TaskBinding.empty(e));Object a=kind==0?"A":1,b=kind==0?"B":2,c=kind==0?"C":3;TaskBinding.push(q,a);TaskBinding.push(q,b);e=assertThrows(Exception.class,()->TaskBinding.push(q,c));assertTrue(TaskBinding.full(e));assertSame(b,TaskBinding.pop(q));assertSame(a,TaskBinding.pop(q));assertTrue(TaskBinding.empty(assertThrows(Exception.class,()->TaskBinding.pop(q))));}}}
